def prorate(amount_cents, days_used, days_in_period):
    """Charge for `days_used` of the period: amount × used / period, rounded to the
    nearest cent (halves round up)."""
    if days_in_period <= 0:
        raise ValueError("days_in_period must be positive")
    if not 0 <= days_used <= days_in_period:
        raise ValueError("days_used out of range")
    # Integer arithmetic only: floating point loses the exact half in values
    # such as 1001 * 15 / 30, so the tie-break would silently round down.
    quotient, remainder = divmod(amount_cents * days_used, days_in_period)
    if remainder * 2 >= days_in_period:
        quotient += 1
    return quotient
"}

